package com.railway.servlet;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.math.BigDecimal;import java.sql.Time;import com.railway.dao.TrainDao;
public class AdminAddTrainServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/admin/add-train.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String no=r.getParameter("number"),name=r.getParameter("name"),src=r.getParameter("source"),dst=r.getParameter("destination");BigDecimal fare=new BigDecimal(r.getParameter("fare"));int cap=Integer.parseInt(r.getParameter("capacity"));if(no==null||!no.matches("[A-Za-z0-9-]{2,20}")||name==null||name.isBlank()||src==null||src.isBlank()||dst==null||dst.isBlank()||src.equalsIgnoreCase(dst)||fare.signum()<0||cap<1||cap>10000)throw new IllegalArgumentException();new TrainDao().add(no,name,src,dst,Time.valueOf(r.getParameter("departure")),Time.valueOf(r.getParameter("arrival")),fare,cap);s.sendRedirect(r.getContextPath()+"/admin");}catch(Exception e){getServletContext().log("Train creation failed",e);r.setAttribute("error","Invalid or duplicate train details. Please check all fields.");doGet(r,s);}}}
